<?php
require_once __DIR__.'/functions.php';
function api_call(string $path,string $method='GET',array $data=[],array $files=[]):array{$url=rtrim(ADMIN_API_URL,'/').'/'.ltrim($path,'/');$ch=curl_init($url);$headers=['Accept: application/json','X-API-Key: '.API_KEY];if(!empty($_SESSION['api_token']))$headers[]='Authorization: Bearer '.$_SESSION['api_token'];if($method==='POST'&&$files){$payload=$data;foreach($files as $k=>$f)$payload[$k]=new CURLFile($f['tmp_name'],$f['type']?:'application/octet-stream',$f['name']);curl_setopt($ch,CURLOPT_POSTFIELDS,$payload);}elseif($method==='POST'){$headers[]='Content-Type: application/json';curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($data));}curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_HTTPHEADER=>$headers,CURLOPT_TIMEOUT=>20,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_FOLLOWLOCATION=>false]);$raw=curl_exec($ch);$err=curl_error($ch);curl_close($ch);if($raw===false||$err)return['ok'=>false,'error'=>'Admin API is unavailable.'];$r=json_decode($raw,true);return is_array($r)?$r:['ok'=>false,'error'=>'Invalid API response.'];}
function api_data(string $path,string $method='GET',array $data=[],array $files=[]):array{$r=api_call($path,$method,$data,$files);if(empty($r['ok'])){if(($r['error']??'')==='Authentication required.')unset($_SESSION['user'],$_SESSION['api_token']);return[];}return$r['data']??[];}
